CREATE TYPE public.app_role AS ENUM ('admin','staff');
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', avatar_url text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_profile ON public.profiles FOR SELECT TO authenticated USING (id=auth.uid());
CREATE POLICY update_profile ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE TABLE public.user_roles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_role ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
CREATE FUNCTION public.create_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES(NEW.id,coalesce(NEW.raw_user_meta_data->>'display_name','')); RETURN NEW; END $$;
CREATE TRIGGER create_user_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_profile();
CREATE TABLE public.products(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL CHECK(length(name) BETWEEN 1 AND 100),description text NOT NULL DEFAULT '',category text NOT NULL DEFAULT 'Clássicas',price numeric(10,2) NOT NULL CHECK(price>=0),image_key text NOT NULL DEFAULT 'margherita',image_url text NOT NULL DEFAULT '',video_url text NOT NULL DEFAULT '',active boolean NOT NULL DEFAULT true,featured boolean NOT NULL DEFAULT false,sort_order integer NOT NULL DEFAULT 0);
GRANT SELECT ON public.products TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.products TO authenticated; GRANT ALL ON public.products TO service_role;
ALTER TABLE public.products ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_catalog ON public.products FOR SELECT TO anon,authenticated USING(active);
CREATE POLICY admin_catalog ON public.products FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.store_settings(id integer PRIMARY KEY DEFAULT 1 CHECK(id=1),is_open boolean NOT NULL DEFAULT true,demo_mode boolean NOT NULL DEFAULT true,opens_at text NOT NULL DEFAULT '18:00',closes_at text NOT NULL DEFAULT '23:00',daily_goal numeric NOT NULL DEFAULT 2000,monthly_goal numeric NOT NULL DEFAULT 60000);
GRANT SELECT ON public.store_settings TO anon; GRANT SELECT,UPDATE ON public.store_settings TO authenticated; GRANT ALL ON public.store_settings TO service_role;
ALTER TABLE public.store_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_settings ON public.store_settings FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY admin_settings ON public.store_settings FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.coupons(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code text UNIQUE NOT NULL,percentage integer NOT NULL CHECK(percentage BETWEEN 1 AND 100),active boolean NOT NULL DEFAULT true,minimum numeric NOT NULL DEFAULT 0 CHECK(minimum>=0),expires_on date);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.coupons TO authenticated; GRANT ALL ON public.coupons TO service_role;
ALTER TABLE public.coupons ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_coupons ON public.coupons FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),number bigint GENERATED ALWAYS AS IDENTITY,customer_name text NOT NULL,phone text NOT NULL,address text NOT NULL DEFAULT '',delivery_method text NOT NULL DEFAULT 'retirada',items jsonb NOT NULL,total numeric NOT NULL CHECK(total>=0),discount numeric NOT NULL DEFAULT 0,status text NOT NULL DEFAULT 'recebido',is_demo boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE ON public.orders TO authenticated; GRANT ALL ON public.orders TO service_role; GRANT USAGE,SELECT ON SEQUENCE public.orders_number_seq TO service_role;
ALTER TABLE public.orders ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_orders ON public.orders FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.expenses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),description text NOT NULL,category text NOT NULL DEFAULT 'Ingredientes',amount numeric NOT NULL CHECK(amount>=0),spent_on date NOT NULL DEFAULT CURRENT_DATE);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.expenses TO authenticated; GRANT ALL ON public.expenses TO service_role;
ALTER TABLE public.expenses ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_expenses ON public.expenses FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
